// UserServiceHandler is an implementation of the roster.api.UserService service.
type UserServiceHandler interface {
	// ListUsers lists users in every state. Only admins may call it.
	ListUsers(context.Context, *connect.Request[api.ListUsersRequest]) (*connect.Response[api.ListUsersResponse], error)
	// GetUser gets a user by resource name.
	GetUser(context.Context, *connect.Request[api.GetUserRequest]) (*connect.Response[api.User], error)
	// BatchGetUsers gets active users by username. Usernames that match no
	// active user are omitted from the response.
	BatchGetUsers(context.Context, *connect.Request[api.BatchGetUsersRequest]) (*connect.Response[api.BatchGetUsersResponse], error)
	// CreateUser creates a user. The first user of an instance becomes an admin.
	// Otherwise, unless an admin calls it, the instance must allow user
	// registration and password sign-up, and the new user gets the USER role.
	CreateUser(context.Context, *connect.Request[api.CreateUserRequest]) (*connect.Response[api.User], error)
	// UpdateUser updates a user. Users may update themselves; admins may update
	// anyone. Changing the password ends the user's other sessions.
	UpdateUser(context.Context, *connect.Request[api.UpdateUserRequest]) (*connect.Response[api.User], error)
	// DeleteUser deletes a user. Users may delete themselves; admins may delete
	// anyone. A user who belongs to any space cannot be deleted.
	DeleteUser(context.Context, *connect.Request[api.DeleteUserRequest]) (*connect.Response[emptypb.Empty], error)
	// ListUserSettings lists the settings of a user. Only the user may call it.
	// The GENERAL setting is always included, with defaults when it was never
	// saved.
	ListUserSettings(context.Context, *connect.Request[api.ListUserSettingsRequest]) (*connect.Response[api.ListUserSettingsResponse], error)
	// GetUserSetting gets a user setting. Only the user may call it.
	GetUserSetting(context.Context, *connect.Request[api.GetUserSettingRequest]) (*connect.Response[api.UserSetting], error)
	// UpdateUserSetting updates a user setting. Only the user may call it, and
	// only the GENERAL and TAGS settings can be updated.
	UpdateUserSetting(context.Context, *connect.Request[api.UpdateUserSettingRequest]) (*connect.Response[api.UserSetting], error)
	// ListUserStats returns note statistics for every user who created at least
	// one matching note the caller can read. Use the parent users/- for all
	// users, or users/{user} for one user.
	ListUserStats(context.Context, *connect.Request[api.ListUserStatsRequest]) (*connect.Response[api.ListUserStatsResponse], error)
	// GetUserStats returns note statistics for one user, counting the user's
	// notes that the caller can read.
	GetUserStats(context.Context, *connect.Request[api.GetUserStatsRequest]) (*connect.Response[api.UserStats], error)
	// GetUserUsage returns a user's usage and the usage limits in effect for the
	// user. Only the user or an admin may call it.
	GetUserUsage(context.Context, *connect.Request[api.GetUserUsageRequest]) (*connect.Response[api.UserUsage], error)
	// ListNoteViews lists a user's note views. Each view is a named, reusable
	// CEL filter (see NoteView.filter); pass its filter string directly to the
	// ListNotes `filter` argument. Only the user may call it.
	ListNoteViews(context.Context, *connect.Request[api.ListNoteViewsRequest]) (*connect.Response[api.ListNoteViewsResponse], error)
	// GetNoteView gets a note view. Only the owner may call it.
	GetNoteView(context.Context, *connect.Request[api.GetNoteViewRequest]) (*connect.Response[api.NoteView], error)
	// CreateNoteView creates a note view for a user. Only the user may call it.
	CreateNoteView(context.Context, *connect.Request[api.CreateNoteViewRequest]) (*connect.Response[api.NoteView], error)
	// UpdateNoteView updates a note view. Only the owner may call it.
	UpdateNoteView(context.Context, *connect.Request[api.UpdateNoteViewRequest]) (*connect.Response[api.NoteView], error)
	// DeleteNoteView deletes a note view. Only the owner may call it.
	DeleteNoteView(context.Context, *connect.Request[api.DeleteNoteViewRequest]) (*connect.Response[emptypb.Empty], error)
	// ListUserNotifications lists a user's notifications. Only the user may call
	// it. Notifications whose notes or space invitation the user can no longer
	// read are left out.
	ListUserNotifications(context.Context, *connect.Request[api.ListUserNotificationsRequest]) (*connect.Response[api.ListUserNotificationsResponse], error)
	// UpdateUserNotification updates a notification's status. Only the receiver
	// may call it.
	UpdateUserNotification(context.Context, *connect.Request[api.UpdateUserNotificationRequest]) (*connect.Response[api.UserNotification], error)
	// DeleteUserNotification permanently deletes a notification. Only the
	// receiver may call it.
	DeleteUserNotification(context.Context, *connect.Request[api.DeleteUserNotificationRequest]) (*connect.Response[emptypb.Empty], error)
	// ListUserWebhooks lists a user's webhooks. Only the user may call it.
	ListUserWebhooks(context.Context, *connect.Request[api.ListUserWebhooksRequest]) (*connect.Response[api.ListUserWebhooksResponse], error)
	// CreateUserWebhook creates a webhook for a user. Only the user may call it.
	// The service generates a signing secret when none is given.
	CreateUserWebhook(context.Context, *connect.Request[api.CreateUserWebhookRequest]) (*connect.Response[api.UserWebhook], error)
	// UpdateUserWebhook updates a webhook. Only the owner may call it.
	UpdateUserWebhook(context.Context, *connect.Request[api.UpdateUserWebhookRequest]) (*connect.Response[api.UserWebhook], error)
	// DeleteUserWebhook deletes a webhook. Only the owner may call it.
	DeleteUserWebhook(context.Context, *connect.Request[api.DeleteUserWebhookRequest]) (*connect.Response[emptypb.Empty], error)
	// GetUserWebhookSigningSecret returns the signing secret of a webhook. Only
	// the owner may call it. The secret is returned only through this call; it
	// is never included in List, Create or Update responses.
	GetUserWebhookSigningSecret(context.Context, *connect.Request[api.GetUserWebhookSigningSecretRequest]) (*connect.Response[api.GetUserWebhookSigningSecretResponse], error)
	// ListLinkedIdentities lists the SSO identities linked to a user. The user
	// and admins may call it.
	ListLinkedIdentities(context.Context, *connect.Request[api.ListLinkedIdentitiesRequest]) (*connect.Response[api.ListLinkedIdentitiesResponse], error)
	// GetLinkedIdentity gets an SSO identity linked to a user. The user and
	// admins may call it.
	GetLinkedIdentity(context.Context, *connect.Request[api.GetLinkedIdentityRequest]) (*connect.Response[api.LinkedIdentity], error)
	// CreateLinkedIdentity completes an OAuth flow and links the resulting SSO
	// identity to the authenticated user, who must be the parent.
	CreateLinkedIdentity(context.Context, *connect.Request[api.CreateLinkedIdentityRequest]) (*connect.Response[api.LinkedIdentity], error)
	// DeleteLinkedIdentity unlinks an SSO identity from a user. The user and
	// admins may call it.
	DeleteLinkedIdentity(context.Context, *connect.Request[api.DeleteLinkedIdentityRequest]) (*connect.Response[emptypb.Empty], error)
	// ListPersonalAccessTokens lists a user's personal access tokens (PATs),
	// without their token values. PATs are long-lived tokens for API and script
	// access, distinct from short-lived JWT access tokens. The user and admins
	// may call it.
	ListPersonalAccessTokens(context.Context, *connect.Request[api.ListPersonalAccessTokensRequest]) (*connect.Response[api.ListPersonalAccessTokensResponse], error)
	// CreatePersonalAccessToken creates a personal access token for a user.
	// Only the user may call it. The token value is returned only once, in the
	// response.
	CreatePersonalAccessToken(context.Context, *connect.Request[api.CreatePersonalAccessTokenRequest]) (*connect.Response[api.CreatePersonalAccessTokenResponse], error)
	// DeletePersonalAccessToken deletes a personal access token, which stops
	// working immediately. Only the owner may call it.
	DeletePersonalAccessToken(context.Context, *connect.Request[api.DeletePersonalAccessTokenRequest]) (*connect.Response[emptypb.Empty], error)
	// ExportNotes writes every note the user created, with comments, archived
	// notes, and attachment files, as a Roster Tracker export file (a ZIP file, see
	// docs/design/notes-export-format.md). Only the user may export their own
	// notes. The body is the archive; content_type is its media type.
	ExportNotes(context.Context, *connect.Request[api.ExportNotesRequest]) (*connect.Response[httpbody.HttpBody], error)
	// ImportNotes uploads a Roster Tracker export file in bounded chunks and imports it
	// into the user's notes. The first call carries the spec and returns an
	// upload_id; later calls carry that upload_id. A finishing call with
	// validate_only returns the plan and keeps the archive staged; a finishing
	// call without it imports and returns the report. Uploads are bound to the
	// authenticated user, expire after 30 minutes of inactivity, and do not
	// survive a server restart.
	ImportNotes(context.Context, *connect.Request[api.ImportNotesRequest]) (*connect.Response[api.ImportNotesResponse], error)
}

